const input = $input.first().json;

// Extract text from various input formats
let rawText = '';
if (input.body) {
  rawText = typeof input.body === 'string' ? input.body : JSON.stringify(input.body);
} else if (input.message) {
  rawText = input.message;
} else if (input.html) {
  rawText = input.html.replace(/<[^>]*>/g, ' ');
} else {
  rawText = JSON.stringify(input);
}

// Clean up whitespace
rawText = rawText.replace(\s+/g, ' ').trim();

return [{ json: { rawText, original: input } }];

const parsed = $input.first().json;
let lead = {};

// Try to parse JSON response from Gemini
try {
  if (parsed.content) {
    lead = JSON.parse(parsed.content);
  } else if (parsed.choices && parsed.choices[0]) {
    lead = JSON.parse(parsed.choices[0].message.content);
  } else if (typeof parsed === 'object') {
    lead = parsed;
  }
} catch (e) {
  // Fallback: extract with regex
  const text = JSON.stringify(parsed);
  lead = {
    name: text.match(/Name:\s*([^\n]+)/)?.[1] || text.match(/([A-Z][a-z]+\s+[A-Z][a-z]+)/)?.[1] || null,
    phone: text.match(/(\+?1?[-.\s]?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4})/)?.[1] || null,
    email: text.match(/([\w.-]+@[\w.-]+\.\w+)/)?.[1] || null,
    service: text.match(/Service:\s*([^\n]+)/)?.[1] || null,
    city: text.match(/City:\s*([^\n]+)/)?.[1] || null,
    urgency: text.match(/Urgency:\s*([^\n]+)/)?.[1] || 'medium'
  };
}

// Validate
const phoneRegex = /^\+?1?[-.\s]?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}$/;
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const validated = {
  name: lead.name || 'Unknown',
  phone: phoneRegex.test(lead.phone) ? lead.phone : null,
  email: emailRegex.test(lead.email) ? lead.email : null,
  service: lead.service || 'General Inquiry',
  city: lead.city || 'Unknown',
  urgency: ['low','medium','high'].includes(lead.urgency) ? lead.urgency : 'medium',
  raw_input: $input.first().json.rawText
};

return [{ json: validated }];
